const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const subject = j.subject || '';
  const text = [j.textPlain, j.textHtml, j.snippet, j.bodyPlain].filter(Boolean).join('\n');
  const combined = `${subject}\n${text}`;
  if (!/potato/i.test(combined)) continue;

  const from = j.from?.value?.[0]?.address || j.from || 'unknown';
  const replyTo = j.replyTo?.value?.[0]?.address || from;

  out.push({
    json: {
      chatId: 'REPLACE_CHAT_ID',
      telegramText: [
        '🥔 Potato email detected',
        `From: ${from}`,
        `Subject: ${subject || '(no subject)'}`,
        `Reply-To: ${replyTo}`,
        '',
        'Tomorrow: connect this to the reply workflow.'
      ].join('\n')
    }
  });
}
return out;
